css:
.vn-root{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:30px;font-family:var(--vn-font);overflow:hidden;background:linear-gradient(90deg,var(--vn-accent) 0%,var(--vn-accent) 50%,#101011 50%,#101011 100%);}
.vn-round{font-size:var(--vn-round-size);font-weight:700;letter-spacing:7px;color:var(--vn-accent);text-transform:uppercase;background:#101011;padding:4px 18px;}
.vn-round:empty{display:none;}
.vn-body{display:flex;align-items:center;}
.vn-side{display:flex;flex-direction:column;align-items:center;gap:18px;width:600px;}
.vn-avatar{width:var(--vn-avatar-size);height:var(--vn-avatar-size);overflow:hidden;background:#0d0d0e;display:flex;align-items:center;justify-content:center;}
.vn-left .vn-avatar{border:1px solid #3a2a12;}
.vn-right .vn-avatar{border:1px solid #3a3a3f;}
.vn-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.vn-avatar img.is-ready{display:block;}
.vn-fallback{font-size:56px;font-weight:700;color:#55554e;}
.vn-avatar:has(img.is-ready) .vn-fallback{display:none;}
.vn-name{font-size:var(--vn-name-size);font-weight:800;letter-spacing:.5px;text-align:center;line-height:1.12;max-width:520px;word-break:break-word;}
.vn-left .vn-name{color:#141210;}
.vn-right .vn-name{color:#f4f4f0;}
.vn-mid{width:120px;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.vn-vs{font-size:26px;font-weight:700;letter-spacing:4px;color:#c9c9c2;background:#101011;padding:8px 0;width:100%;text-align:center;border-top:1px solid #3a3a3f;border-bottom:1px solid #3a3a3f;}
.vn-team{display:flex;align-items:center;gap:10px;max-width:520px;}
.vn-team:not(:has(.vn-team-name:not(:empty),img.is-ready)){display:none;}
.vn-team-logo{position:relative;width:var(--vn-team-logo);height:var(--vn-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.vn-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.vn-team-logo img.is-ready{display:block;}
.vn-team-fallback{width:6px;height:6px;}
.vn-left .vn-team-fallback{background:#141210;}
.vn-right .vn-team-fallback{background:var(--vn-accent);}
.vn-team-logo:has(img.is-ready) .vn-team-fallback{display:none;}
.vn-team-name{font-size:var(--vn-team-size);font-weight:700;letter-spacing:2px;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;}
.vn-left .vn-team-name{color:#3a2a12;}
.vn-right .vn-team-name{color:var(--vn-accent);}
.vn-team-name:empty{display:none;}
